CREATE TABLE IF NOT EXISTS bak_20261105_f2_roadmap AS
SELECT id, status, evidence FROM roadmap_implementation WHERE id IN (1622, 1623, 1677, 1678, 1679, 1680, 1688, 1690, 1713, 1714, 1715, 1716, 1717, 3109, 3111, 3129);

CREATE TABLE IF NOT EXISTS bak_20261105_f2_contracts AS
SELECT class, verify_probe, verify_transport FROM remediation_contracts WHERE class IN ('issue-1000643', 'issue-1000644', 'issue-1000707');

