-- ---- the owner cards: held again, each with an IDENTITY-BOUND line, its default in effect and a closing probe
INSERT INTO human_actions (slug, title, why, default_in_effect, action, url, sev, status, source, created_at, updated_at)
SELECT 'yt-oauth-production-and-analytics', 'YouTube: publish the OAuth app to production and consent again with the three scopes (YT-5 and YT-6)',
 'IDENTITY-BOUND: the Google Cloud project behind the Shorts uploader (gen-lang-client-0589613911) and the YouTube channel are the owner''s own accounts. Publishing the OAuth app (Google Auth Platform, Audience, Publish app) and pressing Allow on the consent screen cannot be done by a loop or a stored credential. Today the app is in Testing, so the stored refresh token expires about weekly (YT-5), and the grant carries the upload scope only, so every hourly read of views and average view duration is refused (youtube.retention_scope warn each hour; all 4 uploaded Shorts have NULL views; YT-6, which also parks YT-12).',
 'Uploads continue until the weekly token expiry; views and average view duration stay NULL and the metric youtube_avg_view_duration_s stays unmeasured (never 0); YT-12 stays parked.',
 'About five minutes. (1) Open https://console.cloud.google.com/auth/audience?project=gen-lang-client-0589613911 and press Publish app (In production). (2) Say "yt consent" in the fleet prompt panel at https://fleet.qnfo.org: the fleet answers with a consent link made by qnfo-youtube-shorts (POST /oauth/consent, valid 10 minutes, scopes youtube.upload, youtube.readonly and yt-analytics.readonly). (3) Open it signed in as the channel owner, press Allow, copy the address of the page you land on (it starts with http://localhost) and paste it into the same panel. The fleet then exchanges the code and installs the new refresh token under the secret-lock lease. The card closes by itself when GET https://qnfo-youtube-shorts.q08.workers.dev/status shows a numeric avg_view_duration_s on a Short.',
 'https://console.cloud.google.com/auth/audience?project=gen-lang-client-0589613911', 'low', 'open', 'session:F2', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = 'yt-oauth-production-and-analytics');

INSERT INTO human_actions (slug, title, why, default_in_effect, action, url, sev, status, source, created_at, updated_at)
SELECT 'yt-channel-branding-owner', 'YouTube channel: your wording for the name, banner and description of the QNFO in plain language series (YT-18)',
 'IDENTITY-BOUND: the channel is the owner''s own account and name; no loop may choose its public identity. It shows a 2025 community post and 19 videos with no series identity.',
 'The channel stays as it is; Shorts keep the tag QNFO IN PLAIN LANGUAGE on screen and the channel context in each description.',
 'Reply in the fleet prompt panel at https://fleet.qnfo.org with the channel name, a one-line description and a banner image, or the word keep. The fleet records your answer in ops_config yt_channel_branding and, for a new name or banner, prepares the YouTube Studio fields for you to paste.',
 'https://fleet.qnfo.org', 'low', 'open', 'session:F2', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = 'yt-channel-branding-owner');

INSERT INTO human_actions (slug, title, why, default_in_effect, action, url, sev, status, source, created_at, updated_at)
SELECT 'jobsearch-ledger-owner-answers-held', 'Two facts only you can state for the job search ledger: your US work-authorization basis and your NL permit type (JS-8)',
 'IDENTITY-BOUND: your immigration and citizenship status is personal data only you can state; the fleet cannot read it from any source and must not guess it. A hand-back tap on 2026-11-04 (issue 1001749) cannot supply it. The job matcher flags roles as needing a visa or citizenship when it does not know; with these two answers it stops flagging roles you can take. Until you answer nothing is blocked: US roles are flagged owner status unverified and non-NL Europe roles are flagged employer-of-record unverified.',
 'The flags stay as they are and no role is dropped or assumed.',
 'Answer in the fleet prompt panel at https://fleet.qnfo.org in one message: "jobsearch ledger: US = citizen | permanent resident | work visa type; NL permit = type, and whether it lets you work in other EU states". The fleet records it in the CV bank and the card closes when jobsearch_meta ledger_open_questions reads 0 (contract owner-card-jobsearch-ledger).',
 'https://fleet.qnfo.org', 'low', 'open', 'session:F2', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = 'jobsearch-ledger-owner-answers-held');

