-- ---- probes that can pass and that measure the definition of done
UPDATE remediation_contracts SET verify_transport = 'd1-query', next_due_at = datetime('now'),
 verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN COALESCE((SELECT last_count FROM jobsearch_feeds WHERE feed = ''publicsector:werkenvoornederland''), 0) >= 10 AND COALESCE((SELECT consecutive_fail FROM jobsearch_feeds WHERE feed = ''publicsector:werkenvoornederland''), 1) = 0 AND (SELECT COUNT(*) FROM (SELECT errors_json FROM jobsearch_runs WHERE finished_at IS NOT NULL ORDER BY id DESC LIMIT 3) WHERE errors_json LIKE ''%publicsector:werkenvoornederland%'') = 0 THEN ''ok'' ELSE ''pending: werkenvoornederland reads '' || COALESCE((SELECT last_count FROM jobsearch_feeds WHERE feed = ''publicsector:werkenvoornederland''), 0) || '' postings (needs 10 or more, none failing in the last 3 runs)'' END AS observed'
 WHERE class = 'issue-1000643';

UPDATE remediation_contracts SET verify_transport = 'd1-query', next_due_at = datetime('now'),
 verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN p.posted >= 3 AND p.refused = 0 AND p.first_post <= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-7 days'') THEN ''ok'' ELSE ''pending: '' || p.posted || '' posted, '' || p.drafted || '' drafted, '' || p.refused || '' refused by Exuvia (needs 3 posted over 7 days and none refused)'' END AS observed FROM (SELECT COALESCE(SUM(outcome = ''posted''), 0) AS posted, COALESCE(SUM(outcome LIKE ''HTTP %''), 0) AS refused, COALESCE(SUM(outcome LIKE ''Evidence-backed%''), 0) AS drafted, MIN(CASE WHEN outcome = ''posted'' THEN ts END) AS first_post FROM decision_log WHERE actor = ''qnfo-memory-mcp:exuvia-engage'') p'
 WHERE class = 'issue-1000644';

UPDATE remediation_contracts SET verify_transport = 'd1-query', next_due_at = datetime('now'),
 verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN b.v LIKE ''%Quantum Laws of Form%'' AND b.v LIKE ''%Dimensionless Physics%'' AND b.v LIKE ''%Auditable Attention%'' AND COALESCE(m.v, '''') = ''on'' THEN ''ok'' ELSE ''pending: the owner bank lists '' || (b.v LIKE ''%Quantum Laws of Form%'') || (b.v LIKE ''%Dimensionless Physics%'') || (b.v LIKE ''%Auditable Attention%'') || '' of the three research papers, research headline flag '' || COALESCE(m.v, ''unset'') END AS observed FROM (SELECT COALESCE((SELECT v FROM jobsearch_bank WHERE k = ''bank''), '''') AS v) b LEFT JOIN (SELECT v FROM jobsearch_meta WHERE k = ''research_headline'') m'
 WHERE class = 'issue-1000707';

-- ---- remainders, each with a named doer and a probe (OWNER-NO-LOOSE-ENDS-1)
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'YT-SCENE-VARIETY-1: Shorts use five themes and eleven templates and every beat looks alike (YT-10 templates 11 to 15, YT-19 motion graphics)',
 'Charter pillar: reach. Owner 2026-11-04: graphics must be professional and not the same every time. Baseline 2026-11-05: container/short_scene.py has 5 backgrounds and 11 beat templates (hook, versus, payoff, meter, dots, bignum, flow, compare, list, cta, plus compatibility stat and points); qnfo-youtube-shorts 0.7.0 only centres each beat. Lever: add templates 11 to 15 (timeline, scale ladder, before-after, formula card as text only), vary the transitions per paper, and give each paper a visual identity under the QNFO in plain language tag; options surveyed in docs/YOUTUBE-PIPELINE.md (Remotion licence, HyperFrames Apache-2.0, Motion Canvas MIT). Doer: a pull request from a session or the Copilot agent: qnfo-code-orchestrator cannot merge it (qnfo-youtube-shorts declares [[containers]], evidence agent_issues 1000597). Render at least one Short per new template on a machine with manim 0.22.0 before the pull request. Definition of done: short_scene.py names YT-SCENE-VARIETY-1 and lists 15 templates in its docstring, and the next 3 uploaded Shorts use at least 3 different templates each.' || char(10) ||
 'code-probe: {"paths": ["qnfo-youtube-shorts/container/short_scene.py"], "contains": "YT-SCENE-VARIETY-1"}',
 'session:F2', 'reach', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'YT-SCENE-VARIETY-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'YT-RENDER-SPEED-1: a 60 s Short takes 306 s on the render container (YT-11, target 120 s)',
 'Charter pillar: reach, cost. Measured 2026-11-05 from youtube_spend (kind container, wall seconds from submit to done) and youtube_videos.duration_s: 143 s for 55.9 s of video, 139 s for 46.3, 122 s for 25.8, 306 s for 59.5 (the first Kokoro render). Target: at most 2 s of container time per second of video. Lever: profile one render first (manim frames versus Kokoro per beat), then replace always_redraw text and the per-frame background updaters in container/short_scene.py (bg_rings rebuilds a Circle per ring per frame, bg_waves re-smooths 4 curves per frame), cache the voice per beat. Doer: a pull request from a session or the Copilot agent (the code loop cannot merge a qnfo-youtube-shorts change, evidence agent_issues 1000597). Definition of done: the contract reads the worst of the last 3 container-seconds-per-video-second ratios at 2.0 or below, and no Short got worse in look.',
 'session:F2', 'cost', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'YT-RENDER-SPEED-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'YT-C2PA-1: sign a C2PA manifest into every Short (remainder of YT-13, BP26-PROVENANCE-MARKING-1)',
 'Charter pillar: security, reach. Baseline 2026-11-05 (qnfo-youtube-shorts 0.7.0): every frame carries the visible label, the mp4 carries comment, description and copyright tags, the sidecar provenance.json (ai_generated, sha256) is kept in R2, and the upload sets containsSyntheticMedia; there is no signed C2PA (Content Credentials) manifest. Lever: add c2patool or the c2pa python package to the render image, sign with a fleet-generated key (a self-signed certificate shows as an unknown signer, which is honest; do not buy or claim a trusted identity), assert c2pa.created with the trainedAlgorithmicMedia digital source type, and store the manifest report next to provenance.json. A signing key is a secret: take the secret-lock lease. Doer: a pull request from a session or the Copilot agent. Definition of done: container/render.py names c2pa, and the first Short rendered after the deploy has a manifest that c2patool reads back with the AI-generated action.',
 'session:F2', 'security', 'low', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'YT-C2PA-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'JOBSEARCH-RESEARCH-HEADLINE-1: a research-portfolio headline and the qnfo.org CV page (remainder of JOBSEARCH-RESEARCH-PORTFOLIO-1)',
 'Charter pillar: personal (job search). qnfo-jobsearch 1.6.0 added the three missing research papers to the owner bank (Quantum Laws of Form, Dimensionless Physics, Proof-of-Concept for Auditable Attention), each with its papers.qnfo.org address because no published paper has a DOI (0 of 723 in living-paper on 2026-11-05). Remaining steps 2 and 3 of agent_issues 1000707: a research-portfolio headline chosen by headline() for research and AI roles (HEADS in worker.js; every sentence stays verbatim in the ledger), and a JSON-LD Person and CV page generated from the same bank (GET /cv.jsonld on qnfo-jobsearch behind the owner session, or the public subset on qnfo.org). Hard limits: nothing the owner has not stated (the IDENTITY-BOUND claims in 1000707 stay out); the bank is the owner''s, edit it only additively. Set jobsearch_meta research_headline = on when the headline ships (the contract of 1000707 reads it). Definition of done: a resume for a quantum or AI-research posting opens with the research headline, the version line names JOBSEARCH-RESEARCH-HEADLINE-1, and the suites pass.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-jobsearch/worker.js' || char(10) ||
 'code-anchor: function headline(clusters) {' || char(10) ||
 'code-probe: {"paths": ["qnfo-jobsearch/worker.js"], "contains": "JOBSEARCH-RESEARCH-HEADLINE-1"}',
 'session:F2', 'reach', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'JOBSEARCH-RESEARCH-HEADLINE-1:%' AND status = 'open');

-- the render-speed issue closes on a measurement, not on a marker (the issue-<id> contract is written here so the birth default cannot stand in for it)
INSERT OR REPLACE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'issue-' || a.id, a.id, 'F2 2026-11-05', 'closes YT-RENDER-SPEED-1 when the last 3 renders took at most 2 s of container time per second of video',
  'SELECT ''ok'' AS expected, CASE WHEN r.n >= 3 AND r.worst <= 2.0 THEN ''ok'' ELSE ''pending: worst of the last '' || r.n || '' renders is '' || COALESCE(ROUND(r.worst, 2), ''n/a'') || '' container seconds per video second (target 2.0 or below)'' END AS observed FROM (SELECT COUNT(*) AS n, MAX(units / duration_s) AS worst FROM (SELECT s.units AS units, v.duration_s AS duration_s FROM youtube_spend s JOIN youtube_videos v ON v.id = s.row_id WHERE s.kind = ''container'' AND v.duration_s > 0 ORDER BY s.id DESC LIMIT 3)) r',
  'd1-query', 3, 'qnfo-cloud-ops', 1, 'active', 'owner-step', datetime('now')
FROM agent_issues a WHERE a.title LIKE 'YT-RENDER-SPEED-1:%' AND a.status = 'open' ORDER BY a.id DESC LIMIT 1;

-- ---- decisions taken by default, with the way back
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'coding-agent (F2 cluster)', 'The voice choice is reversible and the owner delegated decisions (DEFAULT-APPROVE-1); nobody on the fleet can judge audio, the audience can.',
